#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream f1("pracownicy.txt"), f2("projekty.txt");
    map<int, string> imiona;
    map<int, string> dzialy;
    int id; string imie, dzial;
    while (f1 >> id >> imie >> dzial) {
        imiona[id] = imie;
        dzialy[id] = dzial;
    }

    map<int, int> godzPrac;
    map<string, int> godzProj;
    map<string, int> sumDzial;
    map<string, int> cntDzial;
    int pid, godz;
    string proj;
    int totalGodz = 0;
    while (f2 >> pid >> proj >> godz) {
        godzPrac[pid] += godz;
        godzProj[proj] += godz;
        sumDzial[dzialy[pid]] += godz;
        cntDzial[dzialy[pid]]++;
        totalGodz += godz;
    }

    // a) Sortuj pracownikow malejaco wg godzin
    vector<pair<int, string>> ranking;
    for (auto &p : godzPrac) ranking.push_back({p.second, imiona[p.first]});
    sort(ranking.begin(), ranking.end(), [](auto &a, auto &b) {
        return a.first > b.first;
    });

    cout << "a) Godziny pracownikow (malejaco):" << endl;
    for (auto &r : ranking) {
        cout << "   " << r.second << ": " << r.first << endl;
    }

    // b) Srednia godzin/projekt wg dzialu
    cout << endl << "b) Srednia godzin/projekt wg dzialu:" << endl;
    cout << fixed << setprecision(2);
    for (auto &d : sumDzial) {
        cout << "   " << d.first << ": " << (double)d.second / cntDzial[d.first] << endl;
    }

    // c) Projekt z max godzinami
    string maxProj; int maxGodz = 0;
    for (auto &p : godzProj) {
        if (p.second > maxGodz) {
            maxGodz = p.second;
            maxProj = p.first;
        }
    }
    cout << endl << "c) Projekt z max godzinami: " << maxProj << " (" << maxGodz << ")" << endl;

    // d) Powyzej sredniej
    double avg = (double)totalGodz / godzPrac.size();
    cout << endl << "d) Pracownicy powyzej sredniej (" << avg << "):" << endl;
    for (auto &r : ranking) {
        if (r.first > avg) {
            cout << "   " << r.second << ": " << r.first << endl;
        }
    }
    return 0;
}
```

